targets.query:
from(bucket: "batch_job")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._field == "job_start_time" and contains(value: r._measurement, set: ${job_name:json}) and r.svc_name == "$svc_name" and r.svc_env == "$svc_env") 
  |> map(fn: (r) => ({
      _time: time(v: r._value),
      _value: 1
  }))
  |> aggregateWindow(every: ${interval}, fn: sum)
  |> yield(name: "job_count_over_time")
